{"tool": "write_file", "content": """"Routes from warehouses to distribution sites, and which vehicle to send.

A route is a fixed list of roads (see data/network.json), with its length in km.
"""

import math

from logistics.access import can_pass, load_network

# Kits one vehicle carries per trip. Trucks carry the most, so they are sent by default.
CAPACITY = {"truck": 40, "van": 12}
DEFAULT_VEHICLE = "truck"


def routes_between(warehouse_id: str, site: str, network: dict) -> list[dict]:
    return [r for r in network["routes"] if r["from"] == warehouse_id and r["to"] == site]


def best_route(warehouse_id: str, site: str, network: dict | None = None) -> tuple[dict, str] | None:
    """Shortest route from the warehouse to the site and the vehicle to send, or None if no route exists."""
    network = network or load_network()
    options = routes_between(warehouse_id, site, network)
    if not options:
        return None
    return min(options, key=lambda r: (r["km"], r["id"])), DEFAULT_VEHICLE


def _usable(route: dict, network: dict) -> bool:
    """A route is usable if some vehicle (truck or van) may use every road on it."""
    return (
        all(can_pass(road, "truck", network) for road in route["roads"])
        or all(can_pass(road, "van", network) for road in route["roads"])
    )


def passable_route(warehouse_id: str, site: str, network: dict | None = None) -> tuple[dict, str] | None:
    """Shortest usable route from the warehouse to the site and the vehicle to send.

    A truck is sent when it may use every road on the route, otherwise a van.
    Returns None if no route is usable.
    """
    network = network or load_network()
    options = [r for r in routes_between(warehouse_id, site, network) if _usable(r, network)]
    if not options:
        return None
    route = min(options, key=lambda r: (r["km"], r["id"]))
    if all(can_pass(road, "truck", network) for road in route["roads"]):
        return route, "truck"
    return route, "van"


def rerouted_sites(network: dict | None = None) -> list[str]:
    """Sites, in name order, whose passable route differs from the route best_route picks.

    A vehicle-only change does not count: the route itself must differ.
    """
    network = network or load_network()
    rerouted = []
    for site in sorted(network["sites"]):
        warehouses = sorted({r["from"] for r in network["routes"] if r["to"] == site})
        for warehouse_id in warehouses:
            passable = passable_route(warehouse_id, site, network)
            best = best_route(warehouse_id, site, network)
            if passable is None or best is None:
                continue
            if passable[0]["id"] != best[0]["id"]:
                rerouted.append(site)
                break
    return rerouted


def sites_served(warehouse_id: str, network: dict | None = None) -> list[str]:
    """Sites that have at least one route from this warehouse, in name order."""
    network = network or load_network()
    return sorted({r["to"] for r in network["routes"] if r["from"] == warehouse_id})


def trips_needed(kits: int, vehicle: str) -> int:
    return math.ceil(kits / CAPACITY[vehicle])
